package audit;
import java.util.*;import java.security.*;import jdk.internal.org.objectweb.asm.*;
public class BodyProof {
 static List<String> body(byte[]raw,String name){List<String>ops=new ArrayList<>();Map<Label,Integer>labels=new IdentityHashMap<>();List<Label>jumps=new ArrayList<>();new ClassReader(raw).accept(new ClassVisitor(Opcodes.ASM8){public MethodVisitor visitMethod(int a,String n,String d,String s,String[]e){if(!n.equals(name))return null;return new MethodVisitor(Opcodes.ASM8){void add(String x){ops.add(x);}public void visitLabel(Label l){labels.put(l,ops.size());}public void visitInsn(int op){add("I:"+op);}public void visitIntInsn(int op,int v){add("N:"+op+":"+v);}public void visitVarInsn(int op,int v){add("V:"+op+":"+v);}public void visitTypeInsn(int op,String t){add("T:"+op+":"+t);}public void visitFieldInsn(int op,String o,String n,String d){add("F:"+op+":"+o+":"+n+":"+d);}public void visitMethodInsn(int op,String o,String n,String d,boolean itf){add("M:"+op+":"+o+":"+n+":"+d+":"+itf);}public void visitJumpInsn(int op,Label l){int id=jumps.size();jumps.add(l);add("J:"+op+":TARGET"+id);}public void visitLdcInsn(Object x){add("L:"+x.getClass().getName()+":"+x);}public void visitIincInsn(int v,int d){add("INC:"+v+":"+d);}};}},0);for(int i=0;i<ops.size();i++){String s=ops.get(i);if(s.startsWith("J:")){int mark=s.indexOf("TARGET");int id=Integer.parseInt(s.substring(mark+6));ops.set(i,s.substring(0,mark)+labels.get(jumps.get(id)));}}return ops;}
 public static void check(byte[]original,byte[]shell,String method)throws Exception {var a=body(original,method);var b=body(shell,method);if(a.isEmpty()||!a.equals(b))throw new IllegalStateException("original method changed "+method);byte[]h=MessageDigest.getInstance("SHA-256").digest(String.join("\n",a).getBytes(java.nio.charset.StandardCharsets.UTF_8));System.out.println("BODY_IDENTICAL "+method+" instructions="+a.size()+" sha256="+java.util.HexFormat.of().formatHex(h));}
}
